/* View-only shared components. No API requests or business-record writes. */
(function(root){
 function companySlip(order){const text=publish(order),lines=text.split('\n'),suffix=priceN(order.price)>0?'备注：'+publishedFeeNote(order):'',body=lines.slice(1).join('\n');let content=body,fee='';if(suffix&&body.endsWith(suffix)){content=body.slice(0,-suffix.length).replace(/\n$/,'');fee=suffix}return `<section class="zy-slip" aria-label="公司单预览"><header class="zy-slip__head"><strong class="zy-slip__title" data-user-content>${esc(order.title||'')}</strong><span class="zy-slip__stamp" data-user-content>${esc(order.code||'')}</span></header><pre class="zy-slip__lines" data-user-content>${esc(content)}</pre>${fee?`<div class="zy-slip__fee"><pre data-user-content>${esc(fee)}</pre></div>`:''}</section>`}
 function severity(message){if(/失败|连接中断|响应异常|网络中断|登录已过期|权限不足|未获授权|无法连接|服务器异常/.test(message))return 'error';if(/^请|^没有|^未|不能|不支持|已存在|尚未|不可|格式无效|已变化/.test(message))return 'warning';return 'success'}
 function notify(value,kind){let message=String(value?.message||value||'');if(/AI_[A-Z_]+|SyntaxError|TypeError|undefined is|JSON parse|Unexpected token/.test(message))message='操作未完成，请保留输入后重试';kind=kind||severity(message);if(kind==='success'){document.querySelector('.toast')?.remove();const box=document.createElement('div');box.className='toast';box.setAttribute('role','status');box.textContent=message;document.body.append(box);setTimeout(()=>box.remove(),3500);return}if(document.querySelector('#human-save-error')?.textContent===message)return;document.getElementById('zy-action-notice')?.remove();const box=document.createElement('div');box.id='zy-action-notice';box.className='zy-notice zy-notice--'+kind;box.setAttribute('role','alert');const body=document.createElement('span');body.textContent=message;box.append(body);const dismiss=document.createElement('button');dismiss.type='button';dismiss.textContent='×';dismiss.setAttribute('aria-label','关闭提示');dismiss.onclick=()=>box.remove();box.append(dismiss);const parent=document.querySelector('#modal[open]')||document.querySelector('#worker-registration-form')||document.querySelector('#content');const actions=parent?.querySelector(':scope > .actions:last-child');if(actions)actions.before(box);else{box.classList.add('zy-persistent-notice');document.body.append(box)}}
 function editorPreview(){const raw=document.querySelector('#raw'),save=document.querySelector('[data-human-save]');if(!raw||!save)return;let box=document.getElementById('editor-slip-preview');if(!box){box=document.createElement('section');box.id='editor-slip-preview';box.className='editor-slip-preview';save.closest('section')?.append(box)}const values=ZYHumanSave.read(orderFields,$);box.innerHTML='<h3>公司单预览</h3>'+(values.title?companySlip(values):'<p class="muted">填写职位后显示公司单预览。</p>')}
 function decorate(){document.querySelectorAll('aside button:not([aria-label])').forEach(node=>node.setAttribute('aria-label',(node.querySelector(':scope > span')?.textContent||node.textContent).trim()));document.querySelectorAll('input:not([type=hidden]):not([type=checkbox]):not([type=radio]),select,textarea').forEach(n=>n.classList.add('zy-input'));document.querySelectorAll('.fields>label').forEach(n=>n.classList.add('zy-field'));document.querySelectorAll('.human-warning').forEach(n=>n.classList.add('zy-field__hint'));document.querySelectorAll('[role=alert]').forEach(n=>{if(n.textContent.trim()&&!n.classList.contains('zy-notice'))n.classList.add('zy-notice','zy-notice--error')});document.querySelectorAll('dialog:not([data-ui-close-bound])').forEach(dialog=>{dialog.dataset.uiCloseBound='true';dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX>=r.left&&event.clientX<=r.right&&event.clientY>=r.top&&event.clientY<=r.bottom)return;const cancel=new Event('cancel',{cancelable:true});if(dialog.dispatchEvent(cancel))dialog.close()})})}
 async function settingsTab(name){const modal=document.getElementById('modal'),panel=modal.querySelector('[data-settings-panel="'+name+'"]');if(!panel)return;modal.querySelectorAll('[data-settings-panel]').forEach(n=>n.hidden=n!==panel);modal.querySelectorAll('[data-settings-tab]').forEach(n=>{n.setAttribute('aria-selected',String(n.dataset.settingsTab===name));n.tabIndex=n.dataset.settingsTab===name?0:-1});if(name==='classification'&&!panel.dataset.loaded){panel.dataset.loaded='loading';const owner=sessionUser?.id;try{await loadWorkers();await loadJobTaxonomy(true);if(sessionUser?.id!==owner||!panel.isConnected)return;renderClassificationManager();panel.dataset.loaded='true'}catch{panel.dataset.loaded='';panel.querySelector('#settings-classification').innerHTML='<p class="zy-notice zy-notice--error">岗位分类读取失败，请切换页签后重试</p>'}}}
 function mountSettings(name='account'){const modal=document.getElementById('modal');if(!modal.querySelector('#passwordForm'))return;const nodes=[...modal.children],panels={};const definitions=[['account','账号'],...(sessionUser?.role==='admin'?[['team','团队成员'],...(!sessionUser?.readOnly?[['classification','岗位分类']]:[]),['backup','资料备份']]:[])];const tabs=document.createElement('div');tabs.className='settings-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','设置页签');for(const [id,label]of definitions){const panel=document.createElement('section');panel.dataset.settingsPanel=id;panel.className='settings-panel';panel.id='settings-panel-'+id;panel.setAttribute('role','tabpanel');panel.hidden=true;panels[id]=panel;const button=document.createElement('button');button.type='button';button.dataset.settingsTab=id;button.id='settings-tab-'+id;panel.setAttribute('aria-labelledby',button.id);button.textContent=label;button.setAttribute('role','tab');button.setAttribute('aria-controls',panel.id);button.onclick=()=>settingsTab(id);button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const all=[...tabs.children],at=all.indexOf(button),next=all[(at+(event.key==='ArrowRight'?1:all.length-1))%all.length];next.focus();settingsTab(next.dataset.settingsTab)};tabs.append(button)}let group='account';for(const node of nodes){if(node.tagName==='H2'){node.textContent='设置';continue}if(node.tagName==='HR'){node.remove();continue}if(node.id==='teamUsers'||node.tagName==='H3'&&node.textContent.includes('团队账号'))group='team';if(node.tagName==='H3'&&node.textContent.includes('备份'))group='backup';if(node.classList.contains('actions')&&node===nodes.at(-1)){node.classList.add('settings-footer');continue}if(node.tagName==='P'&&node===nodes[1])continue;if(panels[group])panels[group].append(node)}const title=modal.querySelector('h2');title.after(tabs);for(const panel of Object.values(panels))tabs.parentElement.insertBefore(panel,modal.querySelector('.settings-footer'));if(panels.classification){const target=document.createElement('div');target.id='settings-classification';target.textContent='读取中…';panels.classification.append(target)}void settingsTab(panels[name]?name:'account')}
 function confirmAction(title,message){return new Promise(resolve=>{const modal=document.getElementById('modal');let done=false;const finish=answer=>{if(done)return;done=true;modal.oncancel=null;modal.close();resolve(answer)};modal.innerHTML=`<h2>${esc(title)}</h2><p data-user-content>${esc(message)}</p><div class="actions"><button id="ui-confirm-cancel">取消</button><button class="danger" id="ui-confirm-accept">确认删除</button></div>`;modal.querySelector('#ui-confirm-cancel').onclick=()=>finish(false);modal.querySelector('#ui-confirm-accept').onclick=()=>finish(true);modal.oncancel=event=>{event.preventDefault();finish(false)};modal.showModal();modal.querySelector('#ui-confirm-cancel').focus()})}
 root.ZYUI={companySlip,notify,editorPreview,settingsTab,mountSettings,confirm:confirmAction,decorate};if(typeof document==='undefined')return;let scheduled=false;const queue=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;decorate()})};const start=()=>{decorate();new MutationObserver(queue).observe(document.body,{childList:true,subtree:true});document.addEventListener('input',event=>{if(event.target.id?.startsWith('o-'))editorPreview()})};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})(globalThis);
